mapper.select:
/* selectUrlValue - Lee JunYeong */
SELECT T1.CMMNS_CD_VALUE_NM     AS PAGE_URL
     , T1.ADDTNG_MNG_VALUE2     AS STTS
     , T1.ADDTNG_MNG_VALUE5     AS DS_LIST
  FROM SAC100 T1
 WHERE T1.CMMNS_CD_ID       = #{CMMNS_CD}
   AND T1.ADDTNG_MNG_VALUE1 = #{TASKWK_SE_CD}
   AND T1.USE_YN            = 'Y'


  AND T1.ADDTNG_MNG_VALUE2 = #{STEP}


ORDER BY T1.SRTNG_SQNCE

SELECT
/* isry.itgcm.casemng.caseunity.mapper.CaseRegMapper.selectCaseinqList - Lee JunYeong */ TT.* , (SELECT UP_CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = TT.CASE_PRGRS_STTS_SE_CD) AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , ( SELECT LISTAGG(X.CASE_PIC_NO, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC, X.CASE_PIC_NO) FROM SEB150 X WHERE X.CASE_MNG_NO = TT.CASE_MNG_NO AND X.CASE_MNG_ODRNO = TT.CASE_MNG_ODRNO ) AS ENFSN_NO
, ( SELECT LISTAGG(X.PIC_INST_NO, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC, X.CASE_PIC_NO) FROM SEB150 X WHERE X.CASE_MNG_NO = TT.CASE_MNG_NO AND X.CASE_MNG_ODRNO = TT.CASE_MNG_ODRNO ) AS INST_NO , ( SELECT X.FLNM_ENCPT FROM SCA100 X WHERE X.ENFSN_NO = TT.APRV_PIC_NO AND ROWNUM = 1 ) FROM ( SELECT #{TOT_CNT} TOT_CNT , T1.* FROM (
) T1 WHERE 1 = 1
) TT

SELECT
/* isry.itgcm.casemng.caseunity.mapper.CaseRegMapper.selectCaseinqPagingList - Lee JunYeong */ TT.* , A.UP_CMMNS_CD_VALUE AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , TO_CHAR(TT.FRST_REG_DT2, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ FROM ( SELECT T99.* FROM ( SELECT T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.FRST_REG_DT AS FRST_REG_DT2 /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , C##RG.DEC_B64(T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 */ , SUBSTR(T2.TRPR_BRTH_YMD,1,4)||'-'||SUBSTR(T2.TRPR_BRTH_YMD,5,2)||'-'||SUBSTR(T2.TRPR_BRTH_YMD,7,2) AS TRPR_BRTH_YMD /* 대상자출생일자 */ , T2.SXDC_SE_CD AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , C##RG.DEC_B64(X.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명(주담당자기준) */ , Y.PIC_INST_NO AS PIC_INST_NO /* 담당기관(주담당자기준) */ , CASE WHEN X.JBPS_NM IS NOT NULL THEN X.JBPS_NM ELSE (SELECT TT1.CMMNS_CD_VALUE_NM FROM SAC100 TT1 WHERE TT1.CMMNS_CD_ID = 'JBPS_SE_CD' AND TT1.CMMNS_CD_VALUE = X.JBPS_SE_CD) END AS JBPS_NM /* 담당자직위명(주담당자기준) */ , X.JBPS_SE_CD AS JBPS_SE_CD /* 담당자직위구분코드(주담당자기준) */ , Z.INST_NM AS INST_NM /* 담당기관명(주담당자기준) */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , T2.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호 */ , T2.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수 */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD , CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '01' THEN 'REG' /* 등록 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('02','03','06','12') THEN 'PRGRS' /* 진행 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 'TRMN' /* 종결 */ ELSE '' END AS STEP_SE , T2.RCPT_PIC_NO AS RCPT_PIC_NO , Z.CTPV_CD AS CTPV_CD , T1.ORGNL_CASE_MNG_NO AS ORGNL_CASE_MNG_NO , RANK() OVER (ORDER BY T1.CASE_MNG_NO DESC, T1.CASE_MNG_ODRNO DESC) SEQ FROM SEB100 T1 , SEA200 T2 , SCA100 X , SEB150 Y , SAA000 Z WHERE 1=1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND Z.INST_NO = Y.PIC_INST_NO AND X.ENFSN_NO = Y.CASE_PIC_NO AND Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO
) T99 WHERE 1 = 1
AND T99.SEQ >= #{START_IDX} AND T99.SEQ <= #{LAST_IDX}
) TT, SAC100 A WHERE TT.CASE_PRGRS_STTS_SE_CD = A.CMMNS_CD_VALUE(+) AND 'CASE_PRGRS_STTS_SE_CD' = A.CMMNS_CD_ID(+) ORDER BY TT.SEQ

choose.otherwise:

/* 등록일자 조회 */
AND T1.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND T1.FRST_REG_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')

choose.when:

AND (T1.CASE_MNG_NO, T1.CASE_MNG_ODRNO)
    IN (SELECT YY.CASE_MNG_NO,YY.CASE_MNG_ODRNO
        FROM SEB150 YY
        WHERE 1=1
        AND YY.PIC_INST_NO = #{INST_NOS[0]}

   )

choose.otherwise:

	                AND EXISTS (SELECT 1 FROM SEB150 YY
	                WHERE T1.CASE_MNG_NO = YY.CASE_MNG_NO
	                AND T1.CASE_MNG_ODRNO = YY.CASE_MNG_ODRNO
	                AND YY.PIC_INST_NO IN


                            #{item}

	                )

sql.if:

AND EXISTS (SELECT 1 FROM SEB120 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
  AND B.CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
  AND B.DEL_YN         = 'N'
  AND B.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
)


AND EXISTS (SELECT 1 FROM AFA410 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
 AND B.CASE_MNG_ODRNO   = T1.CASE_MNG_ODRNO
 AND B.APRV_YN          = #{APRV_YN}
)

mapper.select:
SELECT /* selectCaseBassDetail - Lee JunYeong */ T3.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T3.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T3.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , T3.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , T3.CASE_BGNG_HR AS CASE_BGNG_HR /* 사례시작시간 */ , T3.CASE_TRMN_YMD AS CASE_TRMN_YMD /* 사례종결일자 */ , T3.CASE_TRMN_HR AS CASE_TRMN_HR /* 사례종결시간 */ , T3.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , T3.GOAL_PLAN_CN AS GOAL_PLAN_CN /* 목표계획내용 */ , T2.CASE_MNG_SE_CD AS CASE_MNG_SE_CD /* 사례관리구분코드 */ , T3.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T3.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T3.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , T2.RESDN_SHAPE_SE_CD AS RESDN_SHAPE_SE_CD /* 거주형태구분코드 */ , T2.FAM_CHAR_SE_CD_NM AS FAM_CHAR_SE_CD /* 가족특성구분코드 */ , T2.RESIDE_SHAPE_SE_CD AS RESIDE_SHAPE_SE_CD /* 주거형태구분코드 */ , T2.RESIDE_SHAPE_ETC_CN AS RESIDE_SHAPE_ETC_CN /* 주거형태기타내용 */ , T3.HEALTH_PROBM_CN AS HEALTH_PROBM_CN /* 건강문제내용 */ , T3.TAKNG_DRFSTF_CN AS TAKNG_DRFSTF_CN /* 복용약물내용 */ , T3.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , SUBSTR(T3.ALTMNT_GROUP_SCLAS_SE_CD,1,3) AS ALTMNT_GROUP_LCLAS_SE_CD /* 배정그룹대분류구분코드 */ , T3.ALTMNT_GROUP_SCLAS_SE_CD AS ALTMNT_GROUP_SCLAS_SE_CD /* 배정그룹소분류구분코드 */ , T3.TAG_NM AS TAG_NM /* 태그명 */ , T3.TAG_NO AS TAG_NO /* 태그번호 */ , NVL(T3.TRPR_PHOTO_ATFINO, T2.TRPR_PHOTO_ATFINO) AS TRPR_PHOTO_ATFINO /* 대상자사진첨부파일번호 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN '' ELSE T1.INDV_IDNTFC_NO END AS INDV_IDNTFC_NO /* 개인식별번호 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN C##RG.DEC_B64(T2.TRPR_NM_ENCPT) ELSE C##RG.DEC_B64(T1.FLNM_ENCPT) END AS TRPR_NM_ENCPT /* 대상자명 */ , C##RG.DEC_B64(T1.RRNO_ENCPT) AS RRNO_ENCPT /* 주민등록번호 */ , TO_CHAR(TO_DATE(REPLACE(T2.TRPR_BRTH_YMD, '-', '')), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.SXDC_SE_CD ELSE T1.SXDC_SE_CD END AS SXDC_SE_CD /* 대상자성별구분코드 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.MRG_YN ELSE T1.MRG_YN END AS MRG_YN /* 결혼여부 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.TRPR_TELNO ELSE T1.WRD_TELNO END AS TRPR_TELNO /* 대상자전화번호 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN C##RG.DEC_B64(T2.MBL_TELNO_ENCPT) ELSE C##RG.DEC_B64(T1.MBL_TELNO_ENCPT) END AS MBL_TELNO_ENCPT /* 휴대전화번호 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN C##RG.DEC_B64(T2.EML_ADDR_ENCPT) ELSE C##RG.DEC_B64(T2.EML_ADDR_ENCPT) END AS EML_ADDR_ENCPT /* 이메일주소 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.SNS_SE_CD ELSE T1.SNS_SE_CD END AS SNS_SE_CD /* SNS구분코드 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN C##RG.DEC_B64(T2.MSNGR_ID_ENCPT) ELSE C##RG.DEC_B64(T1.MSNGR_ID_ENCPT) END AS MSNGR_ID_ENCPT /* 메신저아이디 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.ZIP ELSE T1.ZIP END AS ZIP /* 우편번호 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.PST_ADDR ELSE T1.PST_ADDR END AS PST_ADDR /* 우편주소 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NULL THEN T2.DADDR ELSE T1.DADDR END AS DADDR /* 상세주소 */ , T2.ACBG_SE_CD AS ACBG_SE_CD /* 학력구분코드 */ , T2.GRDTN_STTS_SE_CD AS GRDTN_STTS_SE_CD /* 졸업상태구분코드 */ , T2.GRADE_SE_CD AS GRADE_SE_CD /* 학년구분코드 */ , C##RG.DEC_B64(T2.PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM_ENCPT /* 여권영문성명 */ , T2.TRPR_BCRN_TYPE_SE_CD AS TRPR_BCRN_TYPE_SE_CD /* 대상자배경유형구분코드 */ , T2.TRPR_BCRN_TYPE_RM_NM AS TRPR_BCRN_TYPE_RM_NM /* 대상자배경유형비고명 */ , T2.NLTY_NTN_SE_CD AS NLTY_NTN_SE_CD /* 국적국가구분코드 */ , T2.ENTCNY_YMD AS ENTCNY_YMD /* 입국일자 */ , T2.BRTH_NTN_SE_CD AS BRTH_NTN_SE_CD /* 출생국가구분코드 */ , T2.GROWTH_NTN_SE_CD AS GROWTH_NTN_SE_CD /* 성장국가구분코드 */ , T2.VISA_TYPE_SE_CD AS VISA_TYPE_SE_CD /* 비자유형구분코드 */ , T2.HANAWO_PENU_NO AS HANAWO_PENU_NO /* 하나원기수번호 */ , T2.RELGN_SE_CD AS RELGN_SE_CD /* 종교구분코드 */ , T2.RCPT_PIC_NO AS RCPT_PIC_NO /* 접수담당자번호 */ , T2.RCPT_INST_NO AS RCPT_INST_NO /* 접수기관번호 */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T2.CASE_TRPR_SLCTN_YMD AS CASE_TRPR_SLCTN_YMD /* 사례대상자선정일자 */ , T2.CASE_TRPR_UNSL_CS_CN AS CASE_TRPR_UNSL_CS_CN /* 사례대상자미선정사유내용 */ , C##RG.DEC_B64(T2.PRTCR_NM_ENCPT) AS PRTCR_NM_ENCPT /* 보호자명 */ , T2.TRPR_REL_SE_CD AS TRPR_REL_SE_CD /* 대상자관계구분코드 */ , T2.LIVTGT_YN AS LIVTGT_YN /* 동거여부 */ , T2.PRTCR_AGRE_YN AS PRTCR_AGRE_YN /* 보호자동의여부 */ , T2.PRVC_PVSN_AGRE_YN AS PRVC_PVSN_AGRE_YN /* 개인정보제공동의여부 */ , T2.SRVC_CTRT_AGRE_YN AS SRVC_CTRT_AGRE_YN /* 서비스계약동의여부 */ , T2.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO /* 자격정보관리번호 */ , T2.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호 */ , T2.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수 */ , TO_CHAR(T2.MDFCN_DT, 'YYYYMMDDHH24MISS') AS SEA201_MDFCN_DT /* 수정일시(SEA201) */ , (SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END FROM SEA240 WHERE TRPR_INFO_NO = T2.TRPR_INFO_NO) AS SCHULW_DSCNTC_YN /* 학업중단여부*/ FROM SCA300 T1 , SEA201 T2 , SEB100 T3 WHERE 1 = 1 AND T1.INDV_IDNTFC_NO(+) = T2.INDV_IDNTFC_NO AND T2.TRPR_INFO_NO = T3.TRPR_INFO_NO AND T2.MDFCN_DT = ( SELECT MAX(MDFCN_DT) FROM SEA201 WHERE TRPR_INFO_NO = T2.TRPR_INFO_NO
AND TRMN_CASE_MNG_NO = #{TRMN_CASE_MNG_NO}
AND TRMN_CASE_MNG_ODRNO = #{TRMN_CASE_MNG_ODRNO}
)
AND T3.CASE_MNG_NO = #{CASE_MNG_NO} AND T3.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND T2.TRPR_INFO_NO = #{TRPR_INFO_NO}

mapper.update:
/* updateCasePrgrsSttsSeCd - Lee SeungYeon */
UPDATE SEB100
   SET CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD},
       LAST_MDFR_ID          = #{USER_ID},
       LAST_MDFCN_DT         = SYSDATE
 WHERE CASE_MNG_NO           = #{CASE_MNG_NO}
   AND CASE_MNG_ODRNO        = #{CASE_MNG_ODRNO}

/* updateCaseYngbgs - Lee SeungYeon */
UPDATE SEB130
   SET PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD},
       PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD},
       PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD},
       PROBM_CAS_LCLAS_SE_CD  = #{PROBM_CAS_LCLAS_SE_CD},
       PROBM_CAS_SCLAS_SE_CD  = #{PROBM_CAS_SCLAS_SE_CD},
       PROBM_CAS_ETC_CN       = #{PROBM_CAS_ETC_CN},
       LAST_MDFR_ID           = #{USER_ID},
       LAST_MDFCN_DT          = SYSDATE
 WHERE CASE_MNG_NO       = #{CASE_MNG_NO}
   AND CASE_MNG_ODRNO    = #{CASE_MNG_ODRNO}
   AND PROBM_STTS_CAS_NO = #{PROBM_STTS_CAS_NO}

mapper.delete:
/* deleteCaseYngbgsHstr - Lee JunYeong */
DELETE FROM SEB130
 WHERE PROBM_STTS_CAS_NO = #{PROBM_STTS_CAS_NO}
   AND CASE_MNG_NO       = #{CASE_MNG_NO}
   AND CASE_MNG_ODRNO    = #{CASE_MNG_ODRNO}

