mapper.select:
/* selectDscsnHstrList - Lee SeungYeon */ WITH VW_TRPR_INFO_NO AS ( SELECT T1.TRPR_INFO_NO FROM SEA200 T1 /* 대상자정보 */ WHERE 1 = 1 AND T1.INDV_IDNTFC_NO = ( SELECT X.INDV_IDNTFC_NO FROM SEA200 X /* 대상자정보 */ , SCA300 Y /* 개인정보 */ WHERE X.TRPR_INFO_NO = #{TRPR_INFO_NO} AND X.INDV_IDNTFC_NO = Y.INDV_IDNTFC_NO ) UNION SELECT T1.TRPR_INFO_NO FROM ( SELECT X.RQST_TRPR_INFO_NO AS TRPR_INFO_NO /* 의뢰대상자정보번호 */ FROM SEB400 X /* 서비스제공의뢰 */ WHERE X.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */
UNION SELECT Z.RCPT_TRPR_INFO_NO /* 접수대상자정보번호 */ FROM SEB400 Y /* 서비스제공의뢰 */ , SEB420 Z /* 서비스제공접수 */ WHERE Y.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */ AND Y.SRVC_PVSN_RQST_NO = Z.SRVC_PVSN_RQST_NO /* 서비스제공의뢰번호 */ ) T1 , SEA200 T2 /* 대상자정보 */ WHERE T1.TRPR_INFO_NO = T2.TRPR_INFO_NO UNION SELECT #{TRPR_INFO_NO} FROM DUAL )
SELECT C##RG.DEC_B64(T4.TRPR_NM_ENCPT) AS TRPR_FLNM /* 대상자명 */ , C##RG.DEC_B64(T5.RRNO_ENCPT) AS TRPR_RRNO /* 대상자주민등록번호 */ , T1.DSCSN_YMD AS DSCSN_YMD /* 상담일자 */ , '' AS DSCSN_TASKWK_SE_CD /* 상담업무구분코드 */ , '발굴상담' AS DSCSN_TASKWK_SE_NM /* 상담업무구분명 */ , T1.DSCSN_COURS_SE_CD AS DSCSN_COURS_SE_CD /* 상담경로 */ , '' AS DSCSN_TYPE_SE_CD /* 상담유형 */ , T1.CONSTT_INST_NO AS DSCSN_INST_NO /* 상담기관번호 */ , ( SELECT X.INST_NM FROM SAA000 X WHERE X.DEL_YN = 'N' AND X.INST_NO = T1.CONSTT_INST_NO ) AS DSCSN_INST_NM /* 상담기관명 */ , C##RG.DEC_B64(T3.FLNM_ENCPT) AS CONSTT_NM /* 상담원 */ , T3.WRD_TELNO AS WRD_TELNO /* 상담자유선전화번호 */ , C##RG.DEC_B64(T3.MBL_TELNO_ENCPT) AS MBL_TELNO /* 상담자휴대전화번호 */ , T3.OGDP_INST_NO AS OGDP_INST_NO /* 소속기관번호*/ , ( SELECT X.INST_NM FROM SAA000 X WHERE X.DEL_YN = 'N' AND X.INST_NO = T3.OGDP_INST_NO ) AS OGDP_INST_NM /* 소속기관명 */ , '' AS DSCSN_CHNNEL_SE_CD /* 상담채널구분코드 */ , T1.DSCSN_CN AS DSCSN_CN /* 상담내용 */ FROM SEA100 T1 /* 초기상담 */ , SEA110 T2 /* 상담후조치 */ , SCA100 T3 /* 종사자 */ , SEA200 T4 /* 대상자정보 */ , SCA300 T5 /* 개인정보 */ WHERE 1 = 1 AND T1.ERYY_DSCSN_NO = T2.ERYY_DSCSN_NO /* 초기상담번호 = 초기상담번호 */ AND T2.DEL_YN = 'N' /* 삭제여부 = 'N' */ AND T1.CONSTT_NO = T3.ENFSN_NO (+) /* 상담자번호 = 종사자번호 */ AND T2.TRPR_INFO_NO = T4.TRPR_INFO_NO (+) /* 대상자정보번호 = 대상자정보번호 */ AND T4.INDV_IDNTFC_NO = T5.INDV_IDNTFC_NO(+) /* 개인식별번호 = 개인식별번호 */ AND T2.TRPR_INFO_NO IN ( SELECT X.TRPR_INFO_NO FROM VW_TRPR_INFO_NO X )

/* selectCaseMngHstrList - Lee SeungYeon */ WITH VW_TRPR_INFO_NO AS ( SELECT T1.TRPR_INFO_NO FROM SEA200 T1 /* 대상자정보 */ WHERE 1 = 1 AND T1.INDV_IDNTFC_NO = ( SELECT X.INDV_IDNTFC_NO FROM SEA200 X /* 대상자정보 */ , SCA300 Y /* 개인정보 */ WHERE X.TRPR_INFO_NO = #{TRPR_INFO_NO} AND X.INDV_IDNTFC_NO = Y.INDV_IDNTFC_NO ) UNION SELECT T1.TRPR_INFO_NO FROM ( SELECT X.RQST_TRPR_INFO_NO AS TRPR_INFO_NO /* 의뢰대상자정보번호 */ FROM SEB400 X /* 서비스제공의뢰 */ WHERE X.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */
UNION SELECT Z.RCPT_TRPR_INFO_NO /* 접수대상자정보번호 */ FROM SEB400 Y /* 서비스제공의뢰 */ , SEB420 Z /* 서비스제공접수 */ WHERE Y.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */ AND Y.SRVC_PVSN_RQST_NO = Z.SRVC_PVSN_RQST_NO /* 서비스제공의뢰번호 */ ) T1 , SEA200 T2 /* 대상자정보 */ WHERE T1.TRPR_INFO_NO = T2.TRPR_INFO_NO UNION SELECT #{TRPR_INFO_NO} FROM DUAL )
SELECT T1.CASE_MNG_NO , T1.CASE_MNG_ODRNO , T1.CASE_MNG_BGNG_YMD , T1.CASE_MNG_TRMN_YMD , T1.PRGRS_STTS_SE_NM , T1.TKCG_INST_ID , T1.TKCG_INST_NM , T1.PIC_NM , T1.UNT_TASKWK_SE_CD , T1.UNT_TASKWK_SE_NM , MAX(T1.LAST_MDFCN_DT) AS LAST_MDFCN_DT , T1.WRD_TELNO FROM ( SELECT DISTINCT C##RG.DEC_B64(T3.TRPR_NM_ENCPT) AS TRPR_FLNM /* 대상자성명 */ , C##RG.DEC_B64(T4.RRNO_ENCPT) AS TRPR_RRNO /* 대상자주민등록번호 */ , T2.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T2.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.CASE_BGNG_YMD AS CASE_MNG_BGNG_YMD /* 사례관리 시작일자 */ , T1.CASE_TRMN_YMD AS CASE_MNG_TRMN_YMD /* 사례관리 종결일자 */ , '' AS TRPR_TYPE_SE_CD /* 대상자유형코드 */ , '' AS TRPR_TYPE_SE_NM /* 대상자유형명 */ , T2.CASE_PRGRS_STTS_SE_CD AS PRGRS_STTS_SE_CD /* 진행상태코드 */ , ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'CASE_PRGRS_STTS_TYPE_SE_CD' AND X.CMMNS_CD_VALUE = ( SELECT UP_CMMNS_CD_VALUE FROM SAC100 X WHERE X.CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND X.CMMNS_CD_VALUE = T2.CASE_PRGRS_STTS_SE_CD ) ) AS PRGRS_STTS_SE_NM /* 진행상태명 */ /* 진행상태명 */ , T2.PIC_INST_NO AS TKCG_INST_ID /* 담당기관ID */ , ( SELECT X.INST_NM FROM SAA000 X /* 통합기관 */ WHERE X.DEL_YN = 'N' AND X.INST_NO = T2.PIC_INST_NO ) AS TKCG_INST_NM /* 담당기관명 */ , C##RG.DEC_B64(T5.FLNM_ENCPT) AS PIC_NM /* 담당자명 */ , T5.WRD_TELNO AS WRD_TELNO /* 유선전화번호 */ , C##RG.DEC_B64(T5.MBL_TELNO_ENCPT) AS MBL_TELNO /* 휴대전화번호암호화 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , ( SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND X.CMMNS_CD_VALUE = T1.UNT_TASKWK_SE_CD ) AS UNT_TASKWK_SE_NM /* 단위업무구분명 */ , TO_CHAR(T2.LAST_MDFCN_DT,'YYYYMMDD') AS LAST_MDFCN_DT /* 수정일자 */ , T2.CASE_MNG_HSTR_NO AS CASE_MNG_HSTR_NO /* 사례관리이력번호 */ , '' AS CASE_MNG_TYPE_ID /* 사례관리유형ID */ , '' AS CASE_MNG_STD_TASKWK_PRCS_ID /* 사례관리표준업무처리ID */ , '' AS CASE_MNG_DTL_SE_CD /* 사례관리상세구분코드 */ FROM SEB100 T1 /* 사례기본 */ , SEB110 T2 /* 사례관리이력 */ , SEA200 T3 /* 대상자정보 */ , SCA300 T4 /* 개인정보 */ , SCA100 T5 /* 종사자 */ WHERE T1.CASE_MNG_NO = T2.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T2.CASE_MNG_ODRNO AND T2.TRPR_INFO_NO = T3.TRPR_INFO_NO (+) AND T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO(+) AND T2.CASE_PIC_NO = T5.ENFSN_NO (+) AND T2.TRPR_INFO_NO IN ( SELECT X.TRPR_INFO_NO FROM VW_TRPR_INFO_NO X ) AND T2.CASE_MNG_HSTR_NO IN ( SELECT CASE_MNG_HSTR_NO FROM ( /* 1개사례기준 최근 한건만(기준 : 사례관리번호/차수)*/ SELECT ROW_NUMBER () OVER(PARTITION BY X.CASE_PRGRS_STTS_SE_CD ORDER BY X.FRST_REG_DT DESC) RNUM , X.CASE_MNG_HSTR_NO FROM SEB110 X WHERE X.CASE_MNG_NO = T1.CASE_MNG_NO AND X.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) WHERE RNUM = 1 ) ) T1 GROUP BY T1.CASE_MNG_NO , T1.CASE_MNG_ODRNO , T1.CASE_MNG_BGNG_YMD , T1.CASE_MNG_TRMN_YMD , T1.PRGRS_STTS_SE_NM , T1.TKCG_INST_ID , T1.TKCG_INST_NM , T1.PIC_NM , T1.UNT_TASKWK_SE_CD , T1.UNT_TASKWK_SE_NM , T1.WRD_TELNO ORDER BY T1.CASE_MNG_BGNG_YMD

/* selectSrvcPvsnHstrList - Lee SeungYeon */ WITH VW_TRPR_INFO_NO AS ( SELECT T1.TRPR_INFO_NO FROM SEA200 T1 /* 대상자정보 */ WHERE 1 = 1 AND T1.INDV_IDNTFC_NO = ( SELECT X.INDV_IDNTFC_NO FROM SEA200 X /* 대상자정보 */ , SCA300 Y /* 개인정보 */ WHERE X.TRPR_INFO_NO = #{TRPR_INFO_NO} AND X.INDV_IDNTFC_NO = Y.INDV_IDNTFC_NO ) UNION SELECT T1.TRPR_INFO_NO FROM ( SELECT X.RQST_TRPR_INFO_NO AS TRPR_INFO_NO /* 의뢰대상자정보번호 */ FROM SEB400 X /* 서비스제공의뢰 */ WHERE X.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */
UNION SELECT Z.RCPT_TRPR_INFO_NO /* 접수대상자정보번호 */ FROM SEB400 Y /* 서비스제공의뢰 */ , SEB420 Z /* 서비스제공접수 */ WHERE Y.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */ AND Y.SRVC_PVSN_RQST_NO = Z.SRVC_PVSN_RQST_NO /* 서비스제공의뢰번호 */ ) T1 , SEA200 T2 /* 대상자정보 */ WHERE T1.TRPR_INFO_NO = T2.TRPR_INFO_NO UNION SELECT #{TRPR_INFO_NO} FROM DUAL )
SELECT DISTINCT CASE WHEN T6.INDV_IDNTFC_NO IS NULL THEN NVL(C##RG.DEC_B64(T6.TRPR_NM_ENCPT), C##RG.DEC_B64(T7.FLNM_ENCPT)) ELSE T7.FLNM_ENCPT END AS TRPR_FLNM /* 대상자성명 */ , C##RG.DEC_B64(T7.RRNO_ENCPT) AS TRPR_RRNO /* 대상자주민등록번호 */ , '' AS TRPR_SPCL_INFO_CN /* 대상자특화정보 */ , T1.SRVC_PVSN_NO AS PVSN_SRVC_ID /* 제공서비스ID */ , T4.PVSN_RESRCE_NM AS PVSN_SRVC_NM /* 제공서비스명 */ , T4.RSFR_INST_NO AS PVSN_MBD_ID /* 제공주체ID */ , T5.INST_NM AS PVSN_MBD_NM /* 제공주체명 */ , T1.SRVC_PVSN_BGNG_YMD AS SRVC_BGNG_YMD /* 서비스시작일자 */ , T1.SRVC_PVSN_END_YMD AS SRVC_END_YMD /* 서비스종료일자 */ , T4.RESRCE_SE_CD AS SRVC_PVSN_SE_CD /* 서비스제공구분코드 */ , '' AS SRVC_PVSN_CYCL_SE_CD /* 서비스제공주기코드 */ , '' AS SRVC_PVSN_CYCL_SE_NM /* 서비스제공주기명 */ , T1.SRVC_PVSN_CN AS SRVC_BNF_CN /* 서비스수혜내용 */ , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN /* 서비스제공내용 */ , C##RG.DEC_B64(T8.FLNM_ENCPT) AS SRVC_PVSN_PIC_NM /* 서비스제공담당자명 */ , T8.WRD_TELNO AS WRD_TELNO /* 서비스제공담당자유선전화번호 */ , C##RG.DEC_B64(T8.MBL_TELNO_ENCPT) AS MBL_TELNO /* 서비스제공담당자휴대전화번호 */ FROM SEB500 T1 /* 서비스제공 */ , SEB510 T2 /* 서비스제공대상자 */ , SEB100 T3 /* 사례기본 */ , SDA100 T4 /* 자원기본 */ , SAA000 T5 /* 통합기관 */ , SEA200 T6 /* 대상자정보 */ , SCA300 T7 /* 개인정보 */ , SCA100 T8 /* 종사자 */ WHERE T1.SRVC_PVSN_NO = T2.SRVC_PVSN_NO AND T1.RESRCE_NO = T2.RESRCE_NO AND T1.RESRCE_NO = T4.RESRCE_NO AND T2.CASE_MNG_NO = T3.CASE_MNG_NO AND T2.CASE_MNG_ODRNO = T3.CASE_MNG_ODRNO AND T3.TRPR_INFO_NO IN ( SELECT X.TRPR_INFO_NO FROM VW_TRPR_INFO_NO X ) AND T1.DEL_YN = 'N' AND T2.DEL_YN = 'N' AND T1.PIC_NO = T8.ENFSN_NO (+) AND T4.RSFR_INST_NO = T5.INST_NO (+) AND T3.TRPR_INFO_NO = T6.TRPR_INFO_NO (+) AND T6.INDV_IDNTFC_NO = T7.INDV_IDNTFC_NO(+)

SELECT TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS') AS EXCN_SN /* 실행일련번호 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */
/* 사례진행상태별 건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '01' THEN 1 ELSE 0 END) AS CASE_REG_NOCS /* 사례등록건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '02' THEN 1 ELSE 0 END) AS CASE_PLAN_NOCS /* 사례계획건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '03' THEN 1 ELSE 0 END) AS CASE_EXCN_NOCS /* 사례실행건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '12' THEN 1 ELSE 0 END) AS CASE_TRMN_APLY_NOCS /* 사례종결신청건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '04' THEN 1 ELSE 0 END) AS CASE_TRMN_NOCS /* 사례종결건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '06' THEN 1 ELSE 0 END) AS CASE_AFTFCT_MNG_NOCS /* 사례사후관리건수 */ , SUM(CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '08' THEN 1 ELSE 0 END) AS CASE_AFTFCT_MNG_TRMN_NOCS /* 사례사후관리종결건수 */
/* 시도별 등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '11' THEN 1 ELSE 0 END) AS PRFMNC_SU_REG_NOCS /* 실적서울특별시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '26' THEN 1 ELSE 0 END) AS PRFMNC_BS_REG_NOCS /* 실적부산광역시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '27' THEN 1 ELSE 0 END) AS PRFMNC_DG_REG_NOCS /* 실적대구광역시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '28' THEN 1 ELSE 0 END) AS PRFMNC_IC_REG_NOCS /* 실적인천광역시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '29' THEN 1 ELSE 0 END) AS PRFMNC_GJ_REG_NOCS /* 실적광주광역시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '30' THEN 1 ELSE 0 END) AS PRFMNC_DJ_REG_NOCS /* 실적대전광역시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '31' THEN 1 ELSE 0 END) AS PRFMNC_US_REG_NOCS /* 실적울산등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '36' THEN 1 ELSE 0 END) AS PRFMNC_SJ_REG_NOCS /* 실적세종시등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '41' THEN 1 ELSE 0 END) AS PRFMNC_GG_REG_NOCS /* 실적경기도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '42' THEN 1 ELSE 0 END) AS PRFMNC_GW_REG_NOCS /* 실적강원도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '43' THEN 1 ELSE 0 END) AS PRFMNC_CB_REG_NOCS /* 실적충청북도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '44' THEN 1 ELSE 0 END) AS PRFMNC_CHN_REG_NOCS /* 실적충청남도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '45' THEN 1 ELSE 0 END) AS PRFMNC_JNBK_REG_NOCS /* 실적전라북도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '46' THEN 1 ELSE 0 END) AS PRFMNC_JN_REG_NOCS /* 실적전라남도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '47' THEN 1 ELSE 0 END) AS PRFMNC_GB_REG_NOCS /* 실적경상북도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '48' THEN 1 ELSE 0 END) AS PRFMNC_GN_REG_NOCS /* 실적경상남도등록건수 */ , SUM(CASE WHEN T1.STEP_SE = 'REG' AND T1.CTPV_CD = '50' THEN 1 ELSE 0 END) AS PRFMNC_JJ_REG_NOCS /* 실적제주도등록건수 */
/* 시도별 진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '11' THEN 1 ELSE 0 END) AS PRFMNC_SU_PRGRS_NOCS /* 실적서울특별시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '26' THEN 1 ELSE 0 END) AS PRFMNC_BS_PRGRS_NOCS /* 실적부산광역시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '27' THEN 1 ELSE 0 END) AS PRFMNC_DG_PRGRS_NOCS /* 실적대구광역시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '28' THEN 1 ELSE 0 END) AS PRFMNC_IC_PRGRS_NOCS /* 실적인천광역시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '29' THEN 1 ELSE 0 END) AS PRFMNC_GJ_PRGRS_NOCS /* 실적광주광역시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '30' THEN 1 ELSE 0 END) AS PRFMNC_DJ_PRGRS_NOCS /* 실적대전광역시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '31' THEN 1 ELSE 0 END) AS PRFMNC_US_PRGRS_NOCS /* 실적울산진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '36' THEN 1 ELSE 0 END) AS PRFMNC_SJ_PRGRS_NOCS /* 실적세종시진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '41' THEN 1 ELSE 0 END) AS PRFMNC_GG_PRGRS_NOCS /* 실적경기도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '42' THEN 1 ELSE 0 END) AS PRFMNC_GW_PRGRS_NOCS /* 실적강원도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '43' THEN 1 ELSE 0 END) AS PRFMNC_CB_PRGRS_NOCS /* 실적충청북도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '44' THEN 1 ELSE 0 END) AS PRFMNC_CHN_PRGRS_NOCS /* 실적충청남도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '45' THEN 1 ELSE 0 END) AS PRFMNC_JNBK_PRGRS_NOCS /* 실적전라북도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '46' THEN 1 ELSE 0 END) AS PRFMNC_JN_PRGRS_NOCS /* 실적전라남도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '47' THEN 1 ELSE 0 END) AS PRFMNC_GB_PRGRS_NOCS /* 실적경상북도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '48' THEN 1 ELSE 0 END) AS PRFMNC_GN_PRGRS_NOCS /* 실적경상남도진행건수 */ , SUM(CASE WHEN T1.STEP_SE = 'PRGRS' AND T1.CTPV_CD = '50' THEN 1 ELSE 0 END) AS PRFMNC_JJ_PRGRS_NOCS /* 실적제주도진행건수 */
/* 시도별 종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '11' THEN 1 ELSE 0 END) AS PRFMNC_SU_TRMN_NOCS /* 실적서울특별시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '26' THEN 1 ELSE 0 END) AS PRFMNC_BS_TRMN_NOCS /* 실적부산광역시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '27' THEN 1 ELSE 0 END) AS PRFMNC_DG_TRMN_NOCS /* 실적대구광역시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '28' THEN 1 ELSE 0 END) AS PRFMNC_IC_TRMN_NOCS /* 실적인천광역시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '29' THEN 1 ELSE 0 END) AS PRFMNC_GJ_TRMN_NOCS /* 실적광주광역시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '30' THEN 1 ELSE 0 END) AS PRFMNC_DJ_TRMN_NOCS /* 실적대전광역시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '31' THEN 1 ELSE 0 END) AS PRFMNC_US_TRMN_NOCS /* 실적울산종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '36' THEN 1 ELSE 0 END) AS PRFMNC_SJ_TRMN_NOCS /* 실적세종시종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '41' THEN 1 ELSE 0 END) AS PRFMNC_GG_TRMN_NOCS /* 실적경기도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '42' THEN 1 ELSE 0 END) AS PRFMNC_GW_TRMN_NOCS /* 실적강원도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '43' THEN 1 ELSE 0 END) AS PRFMNC_CB_TRMN_NOCS /* 실적충청북도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '44' THEN 1 ELSE 0 END) AS PRFMNC_CHN_TRMN_NOCS /* 실적충청남도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '45' THEN 1 ELSE 0 END) AS PRFMNC_JNBK_TRMN_NOCS /* 실적전라북도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '46' THEN 1 ELSE 0 END) AS PRFMNC_JN_TRMN_NOCS /* 실적전라남도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '47' THEN 1 ELSE 0 END) AS PRFMNC_GB_TRMN_NOCS /* 실적경상북도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '48' THEN 1 ELSE 0 END) AS PRFMNC_GN_TRMN_NOCS /* 실적경상남도종결건수 */ , SUM(CASE WHEN T1.STEP_SE = 'TRMN' AND T1.CTPV_CD = '50' THEN 1 ELSE 0 END) AS PRFMNC_JJ_TRMN_NOCS /* 실적제주도종결건수 */ FROM (
) T1 WHERE 1 = 1 AND T1.UNT_TASKWK_SE_CD IS NOT NULL GROUP BY T1.UNT_TASKWK_SE_CD

SELECT T1.TASKWK_SE_CD AS TASKWK_SE_CD /* 업무구분코드 */ , ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND CMMNS_CD_VALUE = T1.TASKWK_SE_CD ) AS TASKWK_SE_NM /* 업무구분명 */ , T1.ORGNL_TRPR_MNG_NO AS ORGNL_TRPR_MNG_NO /* 원본대상자관리번호 */ , T1.ORGNL_CASE_MNG_NO AS ORGNL_CASE_MNG_NO /* 원본사례관리번호 */ , T1.DSCSN_INST_NM AS DSCSN_INST_NM /* 상담기관명 */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , T1.CASE_END_YMD AS CASE_END_YMD /* 사례종료일자 */ /* U04(청소년쉼터) */ , T1.ENTRNC_UTZTN_LVNG_TRMN_NM AS ENTRNC_UTZTN_LVNG_TRMN_NM /* 입소이용퇴소종결명 - 입소자/이용자구분 */ , T1.LVNG_CS_CN || CASE WHEN TRIM(T1.LVNG_CS_ETC_CN) IS NOT NULL THEN '(' || TRIM(T1.LVNG_CS_ETC_CN) || ')' ELSE TRIM(T1.LVNG_CS_ETC_CN) END AS LVNG_CS_CN /* 주퇴소사유 */ /* U07(디딤센터) */ , T1.LVNG_TRMN_NM AS LVNG_TRMN_NM /* 퇴소종결명 - 입교종류 */ /* U08(국립청소년인터넷드림마을) */ , T1.ORGNL_HANAWO_PENU_NO AS HANAWO_PENU_NO /* 하나원기수번호 - 캠프기수 */ /* U09(이주배경) */ , T1.BIZ_NM AS BIZ_NM /* 사업명 - 참여사업 */ /* U10(내일이룸) */ , '' AS EDU_NM /* 교육명 */ /* U03(학교밖센터) */ , '' AS OUTC_CN /* 성과내용 */ FROM SEB900 T1 /* 원스크린 */ WHERE T1.FLNM_ENCPT = #{FLNM_ENCPT} AND T1.BRTH_YMD = #{BRTH_YMD} AND T1.SXDC_SE_CD = #{SXDC_SE_CD}
AND ( REGEXP_REPLACE(ETC_TELNO , '[^0-9]') = REGEXP_REPLACE(#{TRPR_TELNO}, '[^0-9]') OR REGEXP_REPLACE(ETC_TELNO1, '[^0-9]') = REGEXP_REPLACE(#{TRPR_TELNO}, '[^0-9]') OR REGEXP_REPLACE(ETC_TELNO2, '[^0-9]') = REGEXP_REPLACE(#{TRPR_TELNO}, '[^0-9]') OR REGEXP_REPLACE(ETC_TELNO , '[^0-9]') = REGEXP_REPLACE(#{MBL_TELNO} , '[^0-9]') OR REGEXP_REPLACE(ETC_TELNO1, '[^0-9]') = REGEXP_REPLACE(#{MBL_TELNO} , '[^0-9]') OR REGEXP_REPLACE(ETC_TELNO2, '[^0-9]') = REGEXP_REPLACE(#{MBL_TELNO} , '[^0-9]') )
AND T1.EML_ADDR_ENCPT = #{EML_ADDR_ENCPT}

/* isry.itgcm.casemng.caseunity.mapper.CaseRegMapper.selectCasePrgrsStts */
SELECT
      A.CASE_PRGRS_STTS_SE_CD
    , B.CMMNS_CD_VALUE_NM AS CASE_PRGRS_STTS_SE_NM
FROM SEB100 A, SAC100 B
WHERE CASE_MNG_NO  = #{CASE_MNG_NO}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND A.CASE_PRGRS_STTS_SE_CD = B.CMMNS_CD_VALUE
AND B.CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD'

        SELECT COUNT(*) AS CNT
		FROM SEB150
		WHERE CASE_MNG_NO  = #{CASE_MNG_NO}
        AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
		AND PCHPRS_YN      = 'Y'

mapper.update:
        UPDATE SEB150
           SET PCHPRS_YN = 'Y'
         WHERE CASE_MNG_NO  = #{CASE_MNG_NO}
         AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}


	            AND CASE_PIC_NO    = #{CASE_PIC_NO}


	            AND ROWNUM = 1
